<?php
declare(strict_types=1);
require_once __DIR__.'/../business/config/customer_membership.php';
require_once __DIR__.'/pwa_step24.php';
$error=null;$catalog=[];$customerCtx=['scope'=>'guest','is_member'=>false];
try{
    $pdo=ps23_db();cm_ensure($pdo);$ctx=ps23_context($pdo);$customerCtx=cm_customer_context($pdo,$ctx['organization_id']);
    foreach(ps23_catalog($pdo,$ctx['organization_id']) as $row){$catalog[(int)$row['id']]=['id'=>(int)$row['id'],'sku'=>$row['sku'],'name'=>$row['product_name'],'image'=>$row['verified_image']??null];}
}catch(Throwable $e){$error=$e->getMessage();}
$catalogJson=json_encode($catalog,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT);
?><!doctype html><html lang="en-IN"><head><?php s24_head('Cart - Healthcare Wellness Club','Review your Healthcare Wellness Club product request cart before checkout.','cart.php','noindex,nofollow,noarchive');?><style>.cart-product-main{display:flex;align-items:center;gap:12px;min-width:0}.cart-thumb{width:70px;height:70px;flex:0 0 70px;border:1px solid #e1e9e4;border-radius:12px;background:#f7faf8;object-fit:contain;padding:4px}.cart-thumb-fallback{display:grid;place-items:center;font-size:.7rem;font-weight:850;color:#367054}.cart-price small{display:block;color:#7c8c84;font-weight:700}.cart-old{text-decoration:line-through;color:#899790}.member-cart{margin-bottom:12px;padding:12px;border:1px solid #dce8e1;border-radius:13px;background:linear-gradient(135deg,#f3fbf6,#fffaf0);font-size:.72rem;color:#567064}.member-cart b{color:#173c2c}.quote-loading{opacity:.65;pointer-events:none}</style></head><body><a class="skip-link" href="#main-content">Skip to main content</a><header class="store-top"><div class="store-bar"><a class="store-brand" href="index.php"><img src="../img/logo.png" alt="Healthcare Wellness Club" width="42" height="42"><span><strong>Healthcare Wellness Club</strong><small><?=!empty($customerCtx['is_member'])?'Club Member Cart':'Your Product Cart'?></small></span></a><nav class="store-actions" aria-label="Cart actions"><?php if(!empty($customerCtx['user'])):?><a class="store-btn" href="../customer_portal.php">My Portal</a><?php endif;?><a class="store-btn" href="index.php">Continue Shopping</a><a class="store-btn primary" href="checkout.php">Checkout</a></nav></div></header><main class="store-shell cart-shell" id="main-content"><nav class="cart-progress" aria-label="Checkout progress"><span class="active"><b>1</b>Shopping Cart</span><i></i><span><b>2</b>Customer Details</span><i></i><span><b>3</b>Request Confirmation</span></nav><section class="cart-heading"><div><div class="store-kicker">YOUR PRODUCT CART</div><h1 id="cart-title"><?=!empty($customerCtx['is_member'])?'Your member-priced cart':'Review your selected products'?></h1><p>Prices and VP are verified securely every time the cart changes.</p></div><a class="store-btn" href="index.php">← Continue Shopping</a></section><?php if($error):?><div class="notice bad" role="alert"><?=ps23_h($error)?></div><?php endif;?><section class="cart-layout"><article class="card cart-products-card"><div id="memberMode" class="member-cart" hidden></div><div class="cart-card-head"><div><span>PRODUCTS</span><h2>Your selection</h2></div><button class="cart-clear-link" id="clearCart" type="button">Clear Cart</button></div><div class="cart-table-labels"><span>Product</span><span>Quantity</span><span>Total</span><span></span></div><div id="cartRows" aria-live="polite"></div></article><aside class="card cart-summary-card"><div class="cart-summary-kicker">ORDER SUMMARY</div><h2>Server-verified total</h2><div class="summary-line"><span>MRP Total</span><strong id="sumMrp">₹0.00</strong></div><div class="summary-line"><span>Your Product Total</span><strong id="sumCustomer">₹0.00</strong></div><div class="summary-line saving-line"><span>Total Discount</span><strong id="sumDiscount">₹0.00</strong></div><div class="summary-line"><span>Total VP</span><strong id="sumVp">0</strong></div><div id="quoteAlert" role="status" aria-live="polite"></div><div class="notice cart-delivery-note"><b>Delivery rule</b><br>Below 100 VP: ₹118 home delivery. 100 VP or more: free home delivery. Club pickup: ₹0.</div><a class="store-btn primary cart-checkout-btn" href="checkout.php">Proceed to Checkout →</a><div class="cart-security">✓ No payment is collected at cart stage<br>✓ Final price is checked again at checkout</div></aside></section><section class="cart-benefits"><article><span>✓</span><div><b>Authentic Products</b><small>Verified catalogue images</small></div></article><article><span>⌂</span><div><b>Flexible Delivery</b><small>Pickup or home delivery</small></div></article><article><span>♢</span><div><b>Secure Price</b><small>Server-side verification</small></div></article><article><span>◎</span><div><b>Order Support</b><small>Coach/Admin confirmation</small></div></article></section></main><footer class="store-footer">No payment is collected at cart stage. <span class="network-badge" data-network-status role="status" aria-live="polite">Online</span></footer><script src="<?=s24_h(s24_asset('store.js'))?>" defer></script><script>
document.addEventListener('DOMContentLoaded',()=>{const catalog=<?=$catalogJson?:'{}'?>;const money=value=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR'}).format(Number(value)||0);const escapeHtml=value=>String(value).replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));let renderSeq=0;
async function quote(cart){const body=new FormData();body.set('cart_json',JSON.stringify(cart));body.set('delivery_mode','club_pickup');const response=await fetch('quote.php',{method:'POST',body,headers:{Accept:'application/json'}});const data=await response.json().catch(()=>({}));if(!response.ok||!data.ok)throw new Error(data.message||'Price quote could not be calculated.');return data;}
async function render(){const seq=++renderSeq;const cart=hwcCart();const box=document.getElementById('cartRows');const alertBox=document.getElementById('quoteAlert');box.innerHTML='';alertBox.innerHTML='';if(!cart.length){box.innerHTML='<div class="empty">Your cart is empty. <a href="index.php">Browse products</a></div>';for(const id of ['sumMrp','sumCustomer','sumDiscount'])document.getElementById(id).textContent=money(0);document.getElementById('sumVp').textContent='0';document.getElementById('memberMode').hidden=true;hwcSyncCartBadge();return}box.classList.add('quote-loading');try{const data=await quote(cart);if(seq!==renderSeq)return;const quoteMap=new Map(data.items.map(item=>[Number(item.id),item]));for(const row of cart){const item=quoteMap.get(Number(row.product_id));if(!item)continue;const product=catalog[Number(item.id)]||{name:item.name,sku:item.sku,image:null};const div=document.createElement('div');div.className='cart-row';const name=escapeHtml(item.name);const image=product.image?`<img class="cart-thumb" src="${escapeHtml(product.image)}" alt="">`:'<span class="cart-thumb cart-thumb-fallback" aria-hidden="true">HWC</span>';const priceMeta=item.unit_price<item.mrp?`<span class="cart-old">MRP ${money(item.mrp)}</span> • Your price ${money(item.unit_price)} • Save ${money(item.discount)}`:`MRP ${money(item.mrp)}`;div.innerHTML=`<div class="cart-product-main">${image}<div><b>${name}</b><div class="meta">Stock ${escapeHtml(item.sku)} • ${priceMeta}</div><div class="meta">${escapeHtml(item.pricing_source)}</div></div></div><input class="store-input" type="number" min="1" max="20" inputmode="numeric" value="${item.qty}" data-q="${item.id}" aria-label="Quantity for ${name}"><div class="cart-price"><strong>${money(item.line_price)}</strong><small>${item.line_vp.toFixed(3).replace(/0+$/,'').replace(/\.$/,'')} VP</small></div><button class="store-btn" type="button" data-r="${item.id}" aria-label="Remove ${name} from cart">×</button>`;box.appendChild(div)}document.getElementById('sumMrp').textContent=money(data.subtotal_mrp);document.getElementById('sumCustomer').textContent=money(data.subtotal_customer);document.getElementById('sumDiscount').textContent=money(data.discount_amount);document.getElementById('sumVp').textContent=Number(data.total_vp).toFixed(3).replace(/0+$/,'').replace(/\.$/,'');const member=document.getElementById('memberMode');member.hidden=false;member.innerHTML=data.is_member?`<b>${escapeHtml(data.discount_label_code||'Club Member')} pricing active.</b> Exact assigned tier pricing and eligible offers are included.`:`<b>Regular customer pricing.</b> Current MRP and any eligible public/regular offer are included.`;box.querySelectorAll('[data-q]').forEach(element=>element.addEventListener('change',()=>{hwcSet(element.dataset.q,element.value);render()}));box.querySelectorAll('[data-r]').forEach(element=>element.addEventListener('click',()=>{hwcRemove(element.dataset.r);hwcAnnounce('Product removed from cart.');render()}));}catch(error){if(seq===renderSeq)alertBox.innerHTML='<div class="notice bad">'+escapeHtml(error.message||'Price quote could not be calculated.')+'</div>'}finally{if(seq===renderSeq)box.classList.remove('quote-loading');hwcSyncCartBadge()}}
document.getElementById('clearCart').addEventListener('click',()=>{hwcClear();hwcAnnounce('Cart cleared.');render()});render()});
</script></body></html>
